#!/usr/bin/env python3
# -*- coding: utf-8 -*-

"""Transform a HWPX template by filling placeholders from JSON.

Key behaviors required by task:
- Replace {{...}} placeholders even when fragmented across multiple <hp:t> nodes
- Normalize budget values by removing commas in the numeric portion
- Append month spans to phase lines (단계1/2/3) based on the date range in the line
- Remove <hp:lineSegArray>/<hp:linesegarray> from paragraphs whose text was modified
- Ensure no '{{' or '}}' remains anywhere in the output XML
"""

from __future__ import annotations

import json
import re
import zipfile
from pathlib import Path

from lxml import etree


JSON_PATH = Path("/root/project_proposal.json")
TEMPLATE_PATH = Path("/root/project_proposal_template.hwpx")
OUTPUT_PATH = Path("/root/project_proposal_ready.hwpx")


PLACEHOLDER_RE = re.compile(r"\{\{([^{}]+?)\}\}")
YEAR_MONTH_RE = re.compile(r"(\d{4})[.\-](\d{2})")


def normalize_budget(value: str) -> str:
    """Remove comma separators from numeric part, preserving leading currency."""
    if value is None:
        return ""
    s = str(value).strip()

    # Preserve any leading currency symbol(s) and whitespace, then normalize the rest.
    # Examples:
    #   ₩450,000,000 -> ₩450000000
    #   1,000,000 -> 1000000
    m = re.match(r"^\s*([₩$€¥]?)(\s*)(.*)$", s)
    if not m:
        return s.replace(",", "")

    currency, ws, rest = m.group(1), m.group(2), m.group(3)
    rest = rest.replace(",", "")
    return f"{currency}{ws}{rest}".strip()


def month_span_from_text(text: str) -> int | None:
    """Compute inclusive month span from date markers found in text.

    Supports:
      - 2026-08 ~ 2026-10
      - 2025.01 ~ 2025.03
      - single month like 2027-01
    """
    matches = YEAR_MONTH_RE.findall(text)
    if not matches:
        return None

    def ym_to_index(y: int, m: int) -> int:
        return y * 12 + m

    # Use first as start, last as end to be tolerant of extra dates in labels.
    y1, m1 = int(matches[0][0]), int(matches[0][1])
    y2, m2 = int(matches[-1][0]), int(matches[-1][1])

    start = ym_to_index(y1, m1)
    end = ym_to_index(y2, m2)
    if end < start:
        # Unexpected ordering; fall back to 1 month.
        return 1
    return (end - start) + 1


def should_append_month_span(text: str) -> bool:
    # Only for phase lines; accept both '단계1' and '1단계' forms.
    if "개월" in text:
        return False
    if "단계" not in text:
        return False
    return month_span_from_text(text) is not None


def append_month_span(text: str) -> str:
    span = month_span_from_text(text)
    if span is None:
        return text
    if re.search(r"\(\s*\d+\s*개월\s*\)", text):
        return text
    return f"{text} ({span}개월)"


def replace_placeholders(text: str, data: dict) -> str:
    def repl(match: re.Match) -> str:
        key = match.group(1).strip()
        if key not in data:
            # Leave it intact so the post-check can fail loudly.
            return match.group(0)
        val = data[key]
        if key == "예산":
            return normalize_budget(str(val))
        return str(val)

    return PLACEHOLDER_RE.sub(repl, text)


def remove_linesegarray(paragraph_el: etree._Element) -> None:
    # Remove any descendant whose local-name is linesegarray/lineSegArray.
    # (Template uses <hp:linesegarray/>)
    for el in list(paragraph_el.iter()):
        if not isinstance(el.tag, str):
            continue
        local = etree.QName(el).localname
        if local.lower() == "linesegarray":
            parent = el.getparent()
            if parent is not None:
                parent.remove(el)


def process_xml(xml_bytes: bytes, data: dict) -> tuple[bytes, bool]:
    """Return (new_xml_bytes, modified_any)."""
    parser = etree.XMLParser(remove_blank_text=False, recover=False)
    root = etree.fromstring(xml_bytes, parser=parser)

    modified_any = False

    # Process each paragraph (<hp:p>) by concatenating all descendant <hp:t> text.
    for p in root.xpath('.//*[local-name()="p"]'):
        t_nodes = p.xpath('.//*[local-name()="t"]')
        if not t_nodes:
            continue

        original = "".join([(n.text or "") for n in t_nodes])
        updated = replace_placeholders(original, data)

        # Append month span after placeholder substitution so dates are present.
        if should_append_month_span(updated):
            updated = append_month_span(updated)

        if updated != original:
            modified_any = True

            # Put all text into the first <hp:t>, clear the rest.
            t_nodes[0].text = updated
            for n in t_nodes[1:]:
                n.text = ""

            # Remove layout cache for modified paragraphs.
            remove_linesegarray(p)

    new_bytes = etree.tostring(
        root,
        encoding="utf-8",
        xml_declaration=True,
        pretty_print=False,
    )

    # Verify no placeholders remain.
    try:
        txt = new_bytes.decode("utf-8")
        if "{{" in txt or "}}" in txt:
            return new_bytes, True  # will be rejected by caller
    except Exception:
        pass

    return new_bytes, modified_any


def main() -> None:
    data = json.loads(JSON_PATH.read_text(encoding="utf-8"))

    if not TEMPLATE_PATH.exists():
        raise SystemExit(f"Template not found: {TEMPLATE_PATH}")

    with zipfile.ZipFile(TEMPLATE_PATH, "r") as zin:
        with zipfile.ZipFile(OUTPUT_PATH, "w", compression=zipfile.ZIP_DEFLATED) as zout:
            for info in zin.infolist():
                raw = zin.read(info.filename)

                lower = info.filename.lower()
                is_content_xml = lower.endswith(".xml") or lower.endswith(".hpf")

                if is_content_xml:
                    try:
                        new_raw, _modified = process_xml(raw, data)
                        # Hard fail if any placeholder remains.
                        new_txt = new_raw.decode("utf-8", errors="ignore")
                        if "{{" in new_txt or "}}" in new_txt:
                            raise ValueError(f"Remaining placeholder in {info.filename}")
                        raw = new_raw
                    except Exception as e:
                        raise SystemExit(f"Failed processing {info.filename}: {e}")

                # Preserve original metadata as much as ZipFile allows.
                out_info = zipfile.ZipInfo(info.filename)
                out_info.date_time = info.date_time
                out_info.external_attr = info.external_attr
                out_info.compress_type = zipfile.ZIP_DEFLATED

                zout.writestr(out_info, raw)

    print(f"Wrote: {OUTPUT_PATH}")


if __name__ == "__main__":
    main()

