import json
import re
import zipfile
from pathlib import Path
import xml.etree.ElementTree as ET


JSON_PATH = Path("/root/project_proposal.json")
TEMPLATE_PATH = Path("/root/project_proposal_template.hwpx")
OUTPUT_PATH = Path("/root/project_proposal_ready.hwpx")


PLACEHOLDER_RE = re.compile(r"\{\{([^{}]+?)\}\}")
YEAR_MONTH_RE = re.compile(r"(\d{4})[.\-](\d{2})")


def localname(tag: str) -> str:
    # Handles "{ns}name" and "name" tags.
    if not isinstance(tag, str):
        return ""
    if tag.startswith("{") and "}" in tag:
        return tag.split("}", 1)[1]
    return tag


def normalize_budget(value: str) -> str:
    """Remove comma separators from numeric part, preserving leading currency."""
    if value is None:
        return ""

    s = str(value).strip()

    # Examples:
    #   ₩450,000,000 -> ₩450000000
    #   1,000,000 -> 1000000
