    """Compute inclusive month span from date markers found in text.

    Supports:
      - 2026-08 ~ 2026-10
      - 2025.01 ~ 2025.03
      - single month like 2027-01
    """
    matches = YEAR_MONTH_RE.findall(text)
    if not matches:
        return None

    def ym_to_index(y: int, m: int) -> int:
        return y * 12 + m

    y1, m1 = int(matches[0][0]), int(matches[0][1])
    y2, m2 = int(matches[-1][0]), int(matches[-1][1])

    start = ym_to_index(y1, m1)
    end = ym_to_index(y2, m2)
    if end < start:
        return 1
    return (end - start) + 1


def should_append_month_span(text: str) -> bool:
    # Only for phase lines; accept both '단계1' and '1단계' forms.
    if "개월" in text:
        return False
    if "단계" not in text:
        return False
    return month_span_from_text(text) is not None


