            return match.group(0)
        val = data[key]
        if key == "예산":
            return normalize_budget(str(val))
        return str(val)

    return PLACEHOLDER_RE.sub(repl, text)


def remove_linesegarray(paragraph_el: ET.Element) -> None:
    # ElementTree has no parent pointers; remove matching children by scanning.
    for parent in list(paragraph_el.iter()):
        for child in list(parent):
            if localname(child.tag).lower() == "linesegarray":
                parent.remove(child)


