        if localname(p.tag) != "p":
            continue

        t_nodes = [el for el in p.iter() if localname(el.tag) == "t"]
        if not t_nodes:
            continue

        original = "".join([(n.text or "") for n in t_nodes])
        updated = replace_placeholders(original, data)

        # Append month span after substitution so date ranges are present.
        if should_append_month_span(updated):
            updated = append_month_span(updated)

        if updated != original:
            modified_any = True

            t_nodes[0].text = updated
            for n in t_nodes[1:]:
                n.text = ""

            remove_linesegarray(p)

